1:/**
2: * OCR utilities for extracting text from scanned PDF pages.
3: *
4: * Pipeline:
5: *   PDF buffer → pdf-to-png-converter (per-page PNG buffers)
6: *              → tesseract.js (WASM, zero native deps)
7: *              → extracted text
8: *
9: * The worker is lazily initialised and reused across requests to avoid
10: * the ~500 ms spin-up cost on every upload.
11: */
12:import { pdfToPng } from "pdf-to-png-converter";
13:import { createWorker, Worker } from "tesseract.js";
14:
15:// ── Worker singleton ─────────────────────────────────────────────────────────
16:
17:let _worker: Worker | null = null;
18:let _workerInitialising: Promise<Worker> | null = null;
19:
20:async function getWorker(): Promise<Worker> {
21:  if (_worker) return _worker;
22:  if (_workerInitialising) return _workerInitialising;
23:
24:  _workerInitialising = createWorker("eng+vie", 1, {
25:    // Suppress verbose Tesseract progress logs in production
26:    logger: () => undefined,
27:  }).then((w) => {
28:    _worker = w;
29:    _workerInitialising = null;
30:    return w;
31:  });
32:
33:  return _workerInitialising;
34:}
35:
36:/**
37: * Release the shared worker. Call once on process exit if needed.
38: * Not required during normal operation — the worker is intentionally long-lived.
39: */
40:export async function terminateOcrWorker(): Promise<void> {
41:  if (_worker) {
42:    await _worker.terminate();
43:    _worker = null;
44:  }
45:}
46:
47:// ── Core OCR function ────────────────────────────────────────────────────────
48:
49:/**
50: * Extract text from a PDF buffer using OCR (Tesseract).
51: *
52: * Each page is rendered to a 2× PNG (for accuracy), then fed to Tesseract.
53: * Pages are processed sequentially to limit peak memory.
54: *
55: * @returns Extracted text, empty string if no pages or OCR yields nothing.
56: */
57:export async function ocrPdf(pdfBuffer: Buffer): Promise<string> {
58:  // Render all pages to PNG buffers.
59:  // pdf-to-png-converter expects ArrayBuffer, not Node Buffer directly.
60:  const pages = await pdfToPng(pdfBuffer.buffer as ArrayBuffer, {
61:    disableFontFace: true,
62:    useSystemFonts: false,
63:    viewportScale: 2.0, // higher resolution → better OCR accuracy
64:  });
65:
66:  if (pages.length === 0) return "";
67:
68:  const worker = await getWorker();
69:  const pageTexts: string[] = [];
70:
71:  for (const page of pages) {
72:    // page.content is a PNG Buffer; skip if undefined (malformed page)
73:    if (!page.content) continue;
74:    const { data } = await worker.recognize(page.content);
75:    const trimmed = data.text.trim();
76:    if (trimmed.length > 0) {
77:      pageTexts.push(trimmed);
78:    }
79:  }
80:
81:  return pageTexts.join("\n\n");
82:}
