1:/**
2: * POST /api/books/split
3: * Analyze book content and detect chapter boundaries using heuristic detection.
4: * Returns a preview of detected chapters for user confirmation.
5: *
6: * Covers: B-17 (heuristic), B-18 (fallback)
7: */
8:import { NextRequest, NextResponse } from "next/server";
9:import { prisma } from "@/lib/prisma";
10:import { detectChapters } from "@/lib/split-chapters";
11:import { z } from "zod";
12:
13:const SUPPORTED_FORMATS = new Set(["pdf", "epub", "docx", "txt", "md"]);
14:
15:const SplitRequestSchema = z.object({
16:  bookId: z.string().min(1, "bookId là bắt buộc"),
17:  format: z.string().min(1),
18:  content: z.string().min(1, "content không được rỗng"),
19:  toc: z.string().nullable().optional(),
20:  pageHeaders: z.array(z.string()).nullable().optional(),
21:  splitConfig: z
22:    .object({
23:      useAI: z.boolean().optional().default(false),
24:      minChapterWords: z.number().optional().default(200),
25:    })
26:    .optional(),
27:});
28:
29:export async function POST(req: NextRequest) {
30:  try {
31:    const body = await req.json();
32:    const parsed = SplitRequestSchema.parse(body);
33:
34:    // Validate format
35:    if (!SUPPORTED_FORMATS.has(parsed.format)) {
36:      return NextResponse.json(
37:        { error: `Định dạng '${parsed.format}' không hỗ trợ. Chấp nhận: pdf, epub, docx, txt, md` },
38:        { status: 400 }
39:      );
40:    }
41:
42:    // Verify book exists
43:    const book = await prisma.course.findUnique({
44:      where: { id: parsed.bookId },
45:    });
46:    if (!book) {
47:      return NextResponse.json({ error: "Sách không tồn tại" }, { status: 404 });
48:    }
49:
50:    // Run heuristic chapter detection
51:    const detected = detectChapters(parsed.content);
52:
53:    // Determine method and build warnings
54:    const warnings: string[] = [];
55:    let method: "heuristic" | "fallback";
56:
57:    if (detected.length >= 2) {
58:      method = "heuristic";
59:    } else {
60:      method = "fallback";
61:      warnings.push(
62:        "Không tìm thấy cấu trúc chương rõ ràng. Toàn bộ nội dung được gom thành 1 phần."
63:      );
64:    }
65:
66:    // Flag short chapters
67:    for (const ch of detected) {
68:      if (ch.short) {
69:        warnings.push(
70:          `Chương "${ch.title}" ngắn (${ch.wordCount} từ). Cân nhắc gộp với chương liền kề.`
71:        );
72:      }
73:    }
74:
75:    // Map to response format
76:    const chapters = detected.map((ch) => ({
77:      index: ch.chapterNumber,
78:      title: ch.title,
79:      wordCount: ch.wordCount,
80:      content: ch.content,
81:    }));
82:
83:    return NextResponse.json({ method, chapters, warnings });
84:  } catch (error) {
85:    if (error instanceof z.ZodError) {
86:      return NextResponse.json({ error: error.issues }, { status: 400 });
87:    }
88:    console.error("Split error:", error);
89:    return NextResponse.json(
90:      { error: "Lỗi server khi phân tích chương" },
91:      { status: 500 }
92:    );
93:  }
94:}
