1:/**
2: * Book parsing utilities for PDF, DOCX, and Markdown files.
3: * Extracted for testability and reuse by /api/books/upload.
4: *
5: * Covers: B-04 (PDF), B-06 (DOCX), B-07 (Markdown)
6: */
7:import { PDFParse } from "pdf-parse";
8:import mammoth from "mammoth";
9:import { ocrPdf } from "./ocr";
10:
11:/**
12: * Extract text from a PDF buffer using pdf-parse v2 (PDFParse class).
13: * Returns a scanned_pdf warning if text is too short (< 100 chars).
14: */
15:export async function parsePdf(
16:  buffer: Buffer
17:): Promise<{ text: string; pages: number; warning?: string }> {
18:  const parser = new PDFParse({ data: new Uint8Array(buffer) });
19:  try {
20:    const result = await parser.getText();
21:    const text = result.text ?? "";
22:    const pages = result.total ?? 0;
23:
24:    if (text.length < 100) {
25:      // Attempt OCR fallback for scanned (image-only) PDFs
26:      try {
27:        const ocrText = await ocrPdf(buffer);
28:        if (ocrText.length > 0) {
29:          return { text: ocrText, pages, warning: "ocr_used" };
30:        }
31:      } catch {
32:        // OCR failed — fall through to scanned_pdf warning
33:      }
34:      return { text, pages, warning: "scanned_pdf" };
35:    }
36:    return { text, pages };
37:  } finally {
38:    await parser.destroy();
39:  }
40:}
41:
42:/**
43: * Extract text and HTML from a DOCX buffer using mammoth.
44: */
45:export async function parseDocx(
46:  buffer: Buffer
47:): Promise<{ text: string; html: string }> {
48:  const [rawResult, htmlResult] = await Promise.all([
49:    mammoth.extractRawText({ buffer }),
50:    mammoth.convertToHtml({ buffer }),
51:  ]);
52:  return {
53:    text: rawResult.value,
54:    html: htmlResult.value,
55:  };
56:}
