58:/**
59: * Split markdown text into chapters by H1 headings (`# Title`).
60: * Returns empty array if no H1 headings found.
61: * Content before the first heading is preserved as a "Preamble" chapter.
62: */
63:export function parseMarkdownChapters(
64:  text: string
65:): { title: string; content: string }[] {
66:  const lines = text.split("\n");
67:  const chapters: { title: string; content: string }[] = [];
68:  let currentTitle: string | null = null;
69:  let currentLines: string[] = [];
70:  let preambleLines: string[] = [];
71:
72:  for (const line of lines) {
73:    // Match only H1: starts with exactly one # followed by space
74:    const match = line.match(/^#\s+(.+)/);
75:    if (match && !line.startsWith("##")) {
76:      // Save previous chapter if any
77:      if (currentTitle !== null) {
78:        chapters.push({
79:          title: currentTitle.trim(),
80:          content: currentLines.join("\n").trim(),
81:        });
82:      } else if (preambleLines.length > 0) {
83:        // Preserve preamble content before first heading
84:        const preambleContent = preambleLines.join("\n").trim();
85:        if (preambleContent.length > 0) {
86:          chapters.push({
87:            title: "Preamble",
88:            content: preambleContent,
89:          });
90:        }
91:      }
92:      currentTitle = match[1];
93:      currentLines = [];
94:    } else if (currentTitle !== null) {
95:      currentLines.push(line);
96:    } else {
97:      // Lines before first H1 → preamble
98:      preambleLines.push(line);
99:    }
100:  }
101:
102:  // Push last chapter
103:  if (currentTitle !== null) {
104:    chapters.push({
105:      title: currentTitle.trim(),
106:      content: currentLines.join("\n").trim(),
107:    });
108:  }
109:
110:  return chapters;
111:}
